mapper.select:
SELECT DISTINCT t.exchange_order_id
FROM quant_trade t
LEFT JOIN quant_order o ON o.credential_id=t.credential_id
    AND o.symbol=t.symbol AND o.exchange_order_id=t.exchange_order_id
WHERE t.credential_id=#{credentialId}
  AND t.symbol=#{symbol}
  AND t.exchange_order_id IS NOT NULL
  AND (o.id IS NULL OR NULLIF(TRIM(o.position_side), '') IS NULL OR o.reduce_only IS NULL)
ORDER BY t.exchange_order_id
LIMIT #{limit}
